-- Migration number: 0002 	 2026-11-17
-- SP-1.8 (cultpodcasts/Api#225): precomputed title / AKA comparison forms for relevance ranking.
--
-- The phrase-first tiers compare an unquoted query with the document's title and each
-- alternative title after normalisation (workers/search/src/ranking.ts, normalizeTitle). Doing
-- that per matching row at read time costs a ~35-deep replace() chain per column per row, which
-- made broad searches 7-14x slower. These columns hold the normalised forms, computed on write.
--
-- Kept in step by triggers, so writers need no change (the SP-1.4 upsert included). Each
-- trigger sets only the *_norm columns: search_docs_au (AFTER UPDATE OF the FTS columns) does not
-- fire, and the AFTER UPDATE OF title, alternative_titles trigger does not fire itself.
--
-- The expressions below are normalizedSql('new.title') / normalizedSql('new.alternative_titles')
-- (and the bare column names for the backfill) verbatim, tests/search-ranking.spec.ts pins them.
-- Change normalizeTitle only together with a new migration that rewrites these triggers and
-- re-runs the backfill.

ALTER TABLE search_docs ADD COLUMN title_norm TEXT NOT NULL DEFAULT '';
ALTER TABLE search_docs ADD COLUMN alternative_titles_norm TEXT NOT NULL DEFAULT '';

UPDATE search_docs SET
	title_norm = trim(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(title, '')), char(39), ''), char(8217), ''), char(8216), ''), char(96), ''), char(46), ' '), char(44), ' '), char(58), ' '), char(59), ' '), char(33), ' '), char(63), ' '), char(45), ' '), char(8211), ' '), char(8212), ' '), char(47), ' '), char(92), ' '), char(38), ' '), char(40), ' '), char(41), ' '), char(91), ' '), char(93), ' '), char(123), ' '), char(125), ' '), char(34), ' '), char(8220), ' '), char(8221), ' '), char(95), ' '), char(43), ' '), char(42), ' '), char(35), ' '), char(124), ' '), char(126), ' '), char(94), ' '), char(9), ' '), char(13), ' '), '  ', ' '), '  ', ' '), '  ', ' '), '  ', ' '), '  ', ' '), ' ' || char(10), char(10)), char(10) || ' ', char(10))),
	alternative_titles_norm = trim(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(alternative_titles, '')), char(39), ''), char(8217), ''), char(8216), ''), char(96), ''), char(46), ' '), char(44), ' '), char(58), ' '), char(59), ' '), char(33), ' '), char(63), ' '), char(45), ' '), char(8211), ' '), char(8212), ' '), char(47), ' '), char(92), ' '), char(38), ' '), char(40), ' '), char(41), ' '), char(91), ' '), char(93), ' '), char(123), ' '), char(125), ' '), char(34), ' '), char(8220), ' '), char(8221), ' '), char(95), ' '), char(43), ' '), char(42), ' '), char(35), ' '), char(124), ' '), char(126), ' '), char(94), ' '), char(9), ' '), char(13), ' '), '  ', ' '), '  ', ' '), '  ', ' '), '  ', ' '), '  ', ' '), ' ' || char(10), char(10)), char(10) || ' ', char(10)));

